            with self.path.open("r", encoding="utf-8") as source:
                document = json.load(source, parse_constant=self._reject_constant)
            entries = document.get("entries") if isinstance(document, dict) else None
            if not isinstance(entries, dict):
                raise ValueError("top-level 'entries' object is missing")
            now = time.time()
            loaded: dict[str, dict[str, Any]] = {}
            discarded = False
            for key, entry in entries.items():
                if not isinstance(key, str) or not key or "/" in key:
                    discarded = True
                    continue
                if not isinstance(entry, dict) or "value" not in entry:
                    discarded = True
                    continue
                expires_at = entry.get("expires_at")
                if expires_at is not None:
                    if (isinstance(expires_at, bool) or
                            not isinstance(expires_at, (int, float)) or
                            not math.isfinite(expires_at)):
                        discarded = True
                        continue
                    if expires_at <= now:
                        discarded = True
                        continue
                loaded[key] = {"value": entry["value"], "expires_at": expires_at}
            self.entries = loaded
            if discarded:
                self._persist_locked()
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            raise RuntimeError(f"cannot load data file {self.path}: {exc}") from exc

