    def _persist_locked(self) -> None:
        parent = self.path.parent
        parent.mkdir(parents=True, exist_ok=True)
        payload = {"entries": self.entries}
        temp_name: str | None = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="w", encoding="utf-8", dir=parent,
                prefix=f".{self.path.name}.", suffix=".tmp", delete=False
            ) as output:
                temp_name = output.name
                json.dump(payload, output, ensure_ascii=False, allow_nan=False,
                          separators=(",", ":"), sort_keys=True)
                output.write("\n")
                output.flush()
                os.fsync(output.fileno())
            os.replace(temp_name, self.path)
            temp_name = None
            try:
                directory_fd = os.open(parent, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                # Directory fsync is unavailable on some platforms/filesystems.
                pass
        finally:
            if temp_name is not None:
                try:
                    os.unlink(temp_name)
                except FileNotFoundError:
                    pass

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            removed = self._remove_expired_locked()
            if removed:
                self._best_effort_persist()
            entry = self.entries.get(key)
            return (False, None) if entry is None else (True, entry["value"])

    def keys(self) -> list[str]:
        with self.lock:
            removed = self._remove_expired_locked()
            if removed:
                self._best_effort_persist()
            return sorted(self.entries)

    def put(self, key: str, value: Any, ttl: float | None) -> bool:
        with self.lock:
            self._remove_expired_locked()
            existed = key in self.entries
            previous = self.entries.get(key)
            expires_at = None if ttl is None else time.time() + ttl
            if expires_at is not None and not math.isfinite(expires_at):
                raise ValueError("ttl_seconds is too large")
            self.entries[key] = {"value": value, "expires_at": expires_at}
            try:
                self._persist_locked()
            except Exception:
                if previous is None:
                    self.entries.pop(key, None)
                else:
                    self.entries[key] = previous
                raise
            return existed

    def delete(self, key: str) -> bool:
        with self.lock:
            self._remove_expired_locked()
            previous = self.entries.pop(key, None)
            if previous is None:
                return False
            try:
                self._persist_locked()
            except Exception:
                self.entries[key] = previous
                raise
            return True

    def compact(self) -> None:
        with self.lock:
            if self._remove_expired_locked():
                self._persist_locked()

    def _best_effort_persist(self) -> None:
        try:
            self._persist_locked()
        except OSError as exc:
            print(f"warning: could not persist expiry cleanup: {exc}", file=sys.stderr)


